async function runAction(act, el4) {
  const id = state.project && state.project.projectId;
  window.dispatchEvent(new CustomEvent("kc:action", { detail: { id: act } }));
  switch (act) {
    case "home":
      navigate("/");
      break;
    // the project manager's File menu: the same things the home sidebar offers
    // from the editor these lead back to the projects page first, where their dialogs live
    case "newProject":
      if (state.view !== "home") navigate("/");
      window.setTimeout(() => window.CollabHome?.newProject(), 0);
      break;
    case "joinLink":
      if (state.view !== "home") navigate("/");
      window.setTimeout(() => window.CollabHome?.join(), 0);
      break;
    case "importGithub":
      location.href = "/github";
      break;
    case "openTrash":
      if (!state.me) {
        toast("Sign in to see your Trash");
        break;
      }
      navigate("/trash");
      break;
    // Log Out works from anywhere, the editor included: it must not depend on the projects page being
    // on screen.  The server drops the session cookie; then the public home page.
    case "signOut":
      if (!state.me) {
        toast("You are not signed in");
        break;
      }
      try {
        await fetch("/auth/logout", { method: "POST", credentials: "same-origin" });
      } catch {
      }
      location.href = "/";
      break;
    case "zoomin":
      zoomBy(1.25);
      break;
    case "zoomout":
      zoomBy(0.8);
      break;
    case "fit":
      fitView();
      break;
    case "grid":
      E.gridOn = !E.gridOn;
      updateGridStatus();
      requestRender();
      break;
    case "snap":
      E.snapOn = !E.snapOn;
      updateGridStatus();
      break;
    case "linemode":
      if (CollabTools.sch && CollabTools.sch.cycleLineMode) {
        CollabTools.sch.cycleLineMode(toolCtx());
        syncSchModes();
      }
      break;
    case "tab-appearance":
      showPane("appearance", true);
      break;
    case "tab-props":
      showPane("props", true);
      break;
    case "tab-peers":
      showPane("peers", true);
      break;
    case "tab-comments":
      showPane("comments", true);
      break;
    case "tab-history":
      showPane("history", true);
      break;
    case "refreshHistory":
      loadHistory();
      break;
    case "about":
      showPopover("about", null, el4);
      break;
    case "archive":
      if (!id) break;
      if (!state.me) {
        toast("Sign in to download the project");
        break;
      }
      if (store.get().can && !store.get().can.copy) {
        toast("The owner does not let viewers download this project", 4e3);
        break;
      }
      location.href = `/api/projects/${id}/archive`;
      break;
    case "github":
      location.href = id ? `/p/${id}/github` : "/github";
      break;
    case "clone":
      if (!id) break;
      if (!state.me) {
        toast("Sign in to clone");
        break;
      }
      try {
        const j = await api4(`/api/projects/${id}/clone`, { method: "POST" });
        toast("Cloned");
        navigate(`/p/${j.projectId}/edit`);
      } catch (e) {
        toast("Clone failed: " + e.message, 4e3);
      }
      break;
    // The share dialog (people, roles, links) is the home's React dialog; anyone in the project can open it
    // to see who has access, and only the owner can change anything.
    case "share":
      if (!id) break;
      if (!state.me) {
        toast("Sign in to share");
        break;
      }
      if (window.CollabHome) window.CollabHome.openShare(id, state.project.name);
      break;
    case "checkpoint":
      if (!id) break;
      saveVersionDialog();
      showPane("history", true);
      break;
    // the Save Version dialog (components/VersionHistory.tsx)
    case "kicad":
      showPopover("kicad", null, el4);
      break;
  }
}
